# frozen_string_literal: true

# Spike for the chart port: a throwaway Phlex SVG must reproduce the DOM recharts 3.8 renders for a monotone line chart with dots and a
# YAxis (the committed oracle/line.html). Decision and the gate contract: dev/decisions/chart.md.
#
#   env -u BUNDLE_GEMFILE bundle exec ruby -Ilib -Itest dev/spikes/chart/line_chart_test.rb
#
# No browser, no network: the oracle is regenerated by `cd dev/react-shadcn-catalog && node ../spikes/chart/oracle_ssr.mjs`.
require "minitest/autorun"
require_relative "line_chart"
require_relative "compare"

class LineChartSpikeTest < Minitest::Test
  ORACLE = File.read(File.expand_path("oracle/line.html", __dir__))
  DATA = [
    { month: "January", desktop: 186 },
    { month: "February", desktop: 305 },
    { month: "March", desktop: 237 },
    { month: "April", desktop: 73 },
    { month: "May", desktop: 209 },
    { month: "June", desktop: 214 }
  ].freeze
  SERIES = [ ChartSpike::Series.new(:desktop, "Desktop", "var(--chart-1)") ].freeze

  def chart(data: DATA)
    ChartSpike::LineChart.new(id: "spike-line", data:, series: SERIES, category_key: :month)
  end

  def test_matches_the_recharts_dom_within_the_tolerance
    comparison = ChartSpike::Compare.new(ORACLE, chart.call)

    assert_empty comparison.errors
    worst = comparison.max_deviation
    puts "\nline chart: #{comparison.compared_attributes} numeric attributes compared, largest deviation #{worst.amount} px " \
         "(#{worst.attribute} at #{worst.path}), tolerance #{ChartSpike::Compare::TOLERANCE}"
    assert_operator worst.amount, :<=, ChartSpike::Compare::TOLERANCE
  end

  def test_the_comparison_is_not_vacuous
    html = chart.call

    [
      [ "C87.733,39.578", "C87.733,41.578" ],
      [ "recharts-line-dot", "recharts-line-dots2" ],
      [ "text-anchor=\"end\"", "text-anchor=\"start\"" ]
    ].each do |from, to|
      refute_empty ChartSpike::Compare.new(ORACLE, mutated(html, from, to)).errors, "#{from} -> #{to} went unnoticed"
    end
  end

  def test_the_monotone_path_equals_d3_curve_monotone_x_rounded_to_three_digits
    d = ChartSpike::MonotoneX.path(chart.points)

    assert_equal "M72,71.187C87.733,39.578,103.467,7.969,119.2,7.969C134.933,7.969,150.667,23.552,166.4,44.094C182.133,64.635,197.867,131.219," \
                 "213.6,131.219C229.333,131.219,245.067,60.74,260.8,58.969C276.533,57.198,292.267,56.755,308,56.313", d
  end

  def test_monotone_degenerate_inputs
    assert_equal "", ChartSpike::MonotoneX.path([])
    assert_equal "M1,2", ChartSpike::MonotoneX.path([ [ 1, 2 ] ])
    assert_equal "M0,0L10,5", ChartSpike::MonotoneX.path([ [ 0, 0 ], [ 10, 5 ] ])
  end

  def test_the_last_y_label_is_moved_inside_the_chart_by_half_its_height
    html = chart.call

    assert_includes html, 'y="8"' # the 320 tick sits on the top edge (coordinate 0) and is shifted by 16 / 2
    assert_includes html, 'y="170"' # the 0 tick keeps its coordinate
  end

  def test_the_point_scale_has_no_band_and_spans_the_plot
    band = chart.band

    assert_in_delta 0.0, band.bandwidth, 0.0
    assert_in_delta 47.2, band.step, 1e-12
    assert_in_delta 72.0, band.tick(0), 1e-12
    assert_in_delta 308.0, band.tick(5), 1e-12
  end

  def test_other_data_changes_the_ticks_and_still_renders_every_point
    data = DATA.map { |row| row.merge(desktop: row[:desktop] * 4) } # max 1220
    html = chart(data:).call

    # literal values of recharts' getNiceTickValues([0, 1220], 5, true, "adaptive"), evaluated in dev/react-shadcn-catalog
    assert_equal [ 0, 350, 700, 1050, 1400 ], chart(data:).y_ticks
    assert_equal 6, html.scan("recharts-line-dot\"").size
  end

  private

  # The mutation must change the HTML, otherwise the "not vacuous" assertion above would pass on an unchanged copy.
  def mutated(html, from, to)
    changed = html.sub(from, to)
    refute_equal html, changed, "#{from.inspect} is not in the rendered HTML"
    changed
  end
end
